app.get('/api/admin/departments',auth,async(_,res)=>{const r=await pool.query('select d.*,b.name branch_name from departments d left join branches b on b.id=d.branch_id where d.is_active=true order by d.name');res.json(r.rows)});
function journalEntryTx(client,{description,referenceType=null,referenceId=null,userId,lines=[]}){const totalD=lines.reduce((a,x)=>a+Number(x.debit||0),0),totalC=lines.reduce((a,x)=>a+Number(x.credit||0),0);if(lines.length<2||Math.abs(totalD-totalC)>0.005)throw new Error('القيد المحاسبي غير متوازن');return (async()=>{const fp=await client.query('select id,is_closed from fiscal_periods where current_date between start_date and end_date order by start_date desc limit 1');if(fp.rowCount&&fp.rows[0].is_closed)throw new Error('الفترة المالية الحالية مغلقة');const no='JE-'+Date.now()+'-'+Math.floor(Math.random()*1000)+'-'+Math.floor(Math.random()*10000);const e=await client.query('insert into journal_entries(entry_no,description,reference_type,reference_id,posted_by) values($1,$2,$3,$4,$5) returning id',[no,description,referenceType,referenceId,userId]);for(const l of lines){const a=await client.query('select id from accounts where code=$1 and is_active=true',[l.account]);if(!a.rowCount)throw new Error('الحساب المحاسبي غير موجود: '+l.account);await client.query('insert into journal_lines(entry_id,account_id,description,debit,credit,cost_center) values($1,$2,$3,$4,$5,$6)',[e.rows[0].id,a.rows[0].id,l.description||description,Number(l.debit||0),Number(l.credit||0),l.costCenter||null])}return e.rows[0].id})()}

async function registerTransactionPosting(client,{transactionType,transactionId,userId}){await client.query('select assert_transaction_postable($1,$2)',[transactionType,transactionId]);const r=await client.query('select register_transaction_posting($1,$2,$3) id',[transactionType,transactionId,userId]);return r.rows[0].id}
async function advancedBootstrap(){await pool.query("INSERT INTO permissions(code,name) VALUES ('crm.manage','إدارة CRM'),('projects.manage','إدارة المشروعات'),('service.manage','إدارة الصيانة والخدمة'),('attendance.manage','إدارة الحضور والانصراف'),('audit.view','عرض سجل المراجعة') ON CONFLICT(code) DO NOTHING; INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON ((r.name IN('admin','manager','sales') AND p.code IN('crm.manage','projects.manage')) OR (r.name IN('admin','manager','warehouse') AND p.code='service.manage') OR (r.name IN('admin','manager') AND p.code='attendance.manage') OR (r.name IN('admin','manager') AND p.code='audit.view')) ON CONFLICT DO NOTHING;") ;await pool.query("CREATE TABLE IF NOT EXISTS invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),invoice_no text UNIQUE NOT NULL,invoice_type text NOT NULL CHECK(invoice_type IN('sale','purchase')),customer_id uuid REFERENCES customers(id),supplier_id uuid REFERENCES suppliers(id),status text NOT NULL DEFAULT 'draft',invoice_date date NOT NULL DEFAULT current_date,total numeric(14,2) NOT NULL DEFAULT 0,tax_amount numeric(14,2) NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS idx_invoices_customer ON invoices(customer_id,invoice_date); CREATE INDEX IF NOT EXISTS idx_invoices_supplier ON invoices(supplier_id,invoice_date); ALTER TABLE invoices ADD COLUMN IF NOT EXISTS tax_amount numeric(14,2) NOT NULL DEFAULT 0;  CREATE TABLE IF NOT EXISTS transaction_postings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),transaction_type text NOT NULL,transaction_id uuid NOT NULL,posted_at timestamptz NOT NULL DEFAULT now(),posted_by uuid REFERENCES users(id),UNIQUE(transaction_type,transaction_id)); CREATE INDEX IF NOT EXISTS idx_transaction_postings_lookup ON transaction_postings(transaction_type,transaction_id); CREATE TABLE IF NOT EXISTS posting_queue(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),transaction_type text NOT NULL,transaction_id uuid NOT NULL,status text NOT NULL DEFAULT 'pending',attempts integer NOT NULL DEFAULT 0,last_error text,created_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz); CREATE INDEX IF NOT EXISTS idx_posting_queue_status ON posting_queue(status,created_at);ALTER TABLE products ADD COLUMN IF NOT EXISTS track_serial boolean NOT NULL DEFAULT false; ALTER TABLE returns ADD COLUMN IF NOT EXISTS tax_amount numeric(14,2) NOT NULL DEFAULT 0; CREATE TABLE IF NOT EXISTS rma_replacements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),rma_id uuid NOT NULL REFERENCES rma_cases(id) ON DELETE CASCADE,old_serial_id uuid NOT NULL REFERENCES serial_numbers(id),new_serial_id uuid NOT NULL REFERENCES serial_numbers(id),warehouse_id uuid NOT NULL REFERENCES warehouses(id),created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(rma_id),UNIQUE(new_serial_id),CHECK(old_serial_id <> new_serial_id)); ALTER TABLE rma_cases ADD COLUMN IF NOT EXISTS replacement_serial_id uuid REFERENCES serial_numbers(id); CREATE INDEX IF NOT EXISTS idx_rma_replacements_old_serial ON rma_replacements(old_serial_id); INSERT INTO permissions(code,name) VALUES('rma.manage','إدارة RMA وخدمة ما بعد البيع') ON CONFLICT(code) DO NOTHING; INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.name IN('admin','manager','sales') AND p.code='rma.manage' ON CONFLICT DO NOTHING;");await pool.query("CREATE TABLE IF NOT EXISTS attendance_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),employee_id uuid NOT NULL REFERENCES employees(id) ON DELETE CASCADE,attendance_date date NOT NULL,check_in timestamptz,check_out timestamptz,status text NOT NULL DEFAULT 'present' CHECK(status IN('present','absent','late','leave','remote')),notes text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(employee_id,attendance_date)); CREATE INDEX IF NOT EXISTS idx_attendance_date ON attendance_records(attendance_date); CREATE TABLE IF NOT EXISTS crm_leads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,company text,phone text,email text,source text,status text NOT NULL DEFAULT 'new',value numeric(14,2) NOT NULL DEFAULT 0,assigned_to uuid REFERENCES users(id),notes text,created_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE IF NOT EXISTS projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_no text UNIQUE NOT NULL,name text NOT NULL,customer_id uuid REFERENCES customers(id),manager_id uuid REFERENCES users(id),status text NOT NULL DEFAULT 'planning',start_date date,end_date date,budget numeric(14,2) NOT NULL DEFAULT 0,description text,created_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE IF NOT EXISTS project_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,title text NOT NULL,assigned_to uuid REFERENCES users(id),status text NOT NULL DEFAULT 'todo',priority text NOT NULL DEFAULT 'normal',due_date date,completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE IF NOT EXISTS service_tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ticket_no text UNIQUE NOT NULL,customer_id uuid REFERENCES customers(id),title text NOT NULL,description text,priority text NOT NULL DEFAULT 'normal',status text NOT NULL DEFAULT 'open',assigned_to uuid REFERENCES users(id),due_date date,created_at timestamptz NOT NULL DEFAULT now(),closed_at timestamptz); ALTER TABLE service_tickets ADD COLUMN IF NOT EXISTS asset_id uuid REFERENCES customer_assets(id) ON DELETE SET NULL; ALTER TABLE service_tickets ADD COLUMN IF NOT EXISTS opened_at timestamptz NOT NULL DEFAULT now(); CREATE TABLE IF NOT EXISTS notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,title text NOT NULL,message text,notification_type text NOT NULL DEFAULT 'info',is_read boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now()); ALTER TABLE notifications ADD COLUMN IF NOT EXISTS read_at timestamptz; UPDATE notifications SET read_at=created_at WHERE is_read=true AND read_at IS NULL; CREATE INDEX IF NOT EXISTS idx_notifications_user_read ON notifications(user_id,read_at); ALTER TABLE notifications ADD COLUMN IF NOT EXISTS read_at timestamptz; UPDATE notifications SET read_at=created_at WHERE is_read=true AND read_at IS NULL; CREATE TABLE IF NOT EXISTS accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text UNIQUE NOT NULL,name text NOT NULL,account_type text NOT NULL CHECK(account_type IN('asset','liability','equity','revenue','expense')),parent_id uuid REFERENCES accounts(id),is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE IF NOT EXISTS fiscal_periods(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,start_date date NOT NULL,end_date date NOT NULL,is_closed boolean NOT NULL DEFAULT false,UNIQUE(start_date,end_date)); CREATE TABLE IF NOT EXISTS journal_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entry_no text UNIQUE NOT NULL,entry_date date NOT NULL DEFAULT current_date,description text,reference_type text,reference_id uuid,posted_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE IF NOT EXISTS journal_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entry_id uuid NOT NULL REFERENCES journal_entries(id) ON DELETE CASCADE,account_id uuid NOT NULL REFERENCES accounts(id),description text,debit numeric(14,2) NOT NULL DEFAULT 0 CHECK(debit>=0),credit numeric(14,2) NOT NULL DEFAULT 0 CHECK(credit>=0),cost_center text,CONSTRAINT journal_line_side CHECK((debit=0 AND credit>0) OR (credit=0 AND debit>0))); CREATE INDEX IF NOT EXISTS idx_journal_entries_date ON journal_entries(entry_date); CREATE INDEX IF NOT EXISTS idx_journal_lines_account ON journal_lines(account_id); INSERT INTO accounts(code,name,account_type) VALUES ('1100','النقدية والخزائن','asset'),('1200','العملاء','asset'),('1300','المخزون','asset'),('2100','الموردون','liability'),('3100','رأس المال','equity'),('4100','المبيعات','revenue'),('4200','إيرادات أخرى','revenue'),('5100','تكلفة المبيعات','expense'),('5200','المصروفات التشغيلية','expense') ON CONFLICT(code) DO NOTHING;");}
app.post('/api/stock/transfer',auth,requirePermission('inventory.manage'),async(req,res)=>{const {productId,fromWarehouseId,toWarehouseId,quantity,notes}=req.body||{};const qty=Number(quantity);if(!productId||!fromWarehouseId||!toWarehouseId||fromWarehouseId===toWarehouseId||qty<=0)return res.status(400).json({error:'بيانات التحويل غير صحيحة'});const client=await pool.connect();try{await client.query('begin');const s=await client.query('select quantity from stock_balances where product_id=$1 and warehouse_id=$2 for update',[productId,fromWarehouseId]);const available=Number(s.rows[0]?.quantity||0);if(available<qty)throw Object.assign(new Error('الرصيد غير كاف في المخزن المصدر'),{status:409});await client.query('update stock_balances set quantity=quantity-$1 where product_id=$2 and warehouse_id=$3',[qty,productId,fromWarehouseId]);await client.query('insert into stock_balances(product_id,warehouse_id,quantity) values($1,$2,$3) on conflict(product_id,warehouse_id) do update set quantity=stock_balances.quantity+$3',[productId,toWarehouseId,qty]);await client.query('insert into product_stock_movements(product_id,warehouse_id,movement_type,quantity,reference,notes) values($1,$2,$3,$4,$5,$6)',[productId,fromWarehouseId,'transfer',-qty,'transfer',notes||'']);await client.query('insert into product_stock_movements(product_id,warehouse_id,movement_type,quantity,reference,notes) values($1,$2,$3,$4,$5,$6)',[productId,toWarehouseId,'transfer',qty,'transfer',notes||'']);await client.query('commit');res.status(201).json({success:true})}catch(e){await client.query('rollback');res.status(e.status||500).json({error:e.message})}finally{client.release()}});
app.get('/api/inventory/adjustments',auth,requirePermission('reports.view'),async(_,res)=>{const r=await pool.query('select a.*,w.name warehouse_name from inventory_adjustments a join warehouses w on w.id=a.warehouse_id order by a.created_at desc');res.json(r.rows)});
app.post('/api/inventory/adjustments',auth,requirePermission('inventory.manage'),async(req,res)=>{const {warehouseId,reason,items=[]}=req.body||{};if(!warehouseId||!items.length)return res.status(400).json({error:'المخزن وأصناف التسوية مطلوبان'});const client=await pool.connect();try{await client.query('begin');const no='ADJ-'+Date.now();const adj=await client.query('insert into inventory_adjustments(adjustment_no,warehouse_id,reason,created_by) values($1,$2,$3,$4) returning *',[no,warehouseId,reason||'',req.user.sub]);for(const x of items){const delta=Number(x.quantityDelta);if(!x.productId||!Number.isFinite(delta)||delta===0)throw new Error('بيانات التسوية غير صحيحة');const b=await client.query('select quantity from stock_balances where product_id=$1 and warehouse_id=$2 for update',[x.productId,warehouseId]);const current=Number(b.rows[0]?.quantity||0);if(current+delta<0)throw new Error('التسوية تؤدي إلى مخزون سالب');await client.query('insert into stock_balances(product_id,warehouse_id,quantity) values($1,$2,$3) on conflict(product_id,warehouse_id) do update set quantity=stock_balances.quantity+$3',[x.productId,warehouseId,delta]);await client.query('insert into inventory_adjustment_items(adjustment_id,product_id,quantity_delta) values($1,$2,$3)',[adj.rows[0].id,x.productId,delta]);await client.query('insert into product_stock_movements(product_id,warehouse_id,movement_type,quantity,reference,notes) values($1,$2,\'adjustment\',$3,$4,$5)',[x.productId,warehouseId,delta,no,reason||'']);}await client.query('insert into audit_logs(user_id,action,entity,entity_id,details) values($1,$2,$3,$4,$5)',[req.user.sub,'inventory.adjustment','inventory_adjustment',adj.rows[0].id,JSON.stringify({items:items.length})]);await client.query('commit');res.status(201).json(adj.rows[0])}catch(e){await client.query('rollback');res.status(400).json({error:e.message})}finally{client.release()}});
app.get('/api/inventory/serials',auth,requirePermission('reports.view'),async(_,res)=>{const r=await pool.query('select s.*,p.code product_code,p.name product_name,w.name warehouse_name,c.name customer_name from serial_numbers s join products p on p.id=s.product_id left join warehouses w on w.id=s.warehouse_id left join customers c on c.id=s.customer_id order by s.created_at desc');res.json(r.rows)});
app.post('/api/inventory/serials',auth,requirePermission('inventory.manage'),async(req,res)=>{const {productId,serialNo,warehouseId,status='in_stock'}=req.body||{};if(!productId||!serialNo||!warehouseId)return res.status(400).json({error:'الصنف والرقم التسلسلي والمخزن مطلوبون'});if(!['in_stock','sold','repair','returned'].includes(status))return res.status(400).json({error:'حالة Serial غير صحيحة'});const client=await pool.connect();try{await client.query('begin');const r=await client.query('insert into serial_numbers(product_id,serial_no,warehouse_id,status) values($1,$2,$3,$4) returning *',[productId,serialNo,warehouseId,status]);if(status==='in_stock'){await client.query('insert into stock_balances(product_id,warehouse_id,quantity) values($1,$2,1) on conflict(product_id,warehouse_id) do update set quantity=stock_balances.quantity+1',[productId,warehouseId]);await client.query('insert into product_stock_movements(product_id,warehouse_id,movement_type,quantity,reference,notes) values($1,$2,\'in\',1,$3,$4)',[productId,warehouseId,'SER-'+r.rows[0].serial_no,'Serial registration']);}await client.query('insert into audit_logs(user_id,action,entity,entity_id,details) values($1,$2,$3,$4,$5)',[req.user.sub,'serial.create','serial_number',r.rows[0].id,JSON.stringify({productId,warehouseId,status})]);await client.query('commit');res.status(201).json(r.rows[0])}catch(e){await client.query('rollback');res.status(400).json({error:e.message})}finally{client.release()}});
app.post('/api/inventory/serials/assign',auth,requirePermission('inventory.manage'),async(req,res)=>{const {invoiceItemId,serialIds=[]}=req.body||{};if(!invoiceItemId||!Array.isArray(serialIds)||!serialIds.length)return res.status(400).json({error:'بند الفاتورة والأرقام التسلسلية مطلوبة'});const client=await pool.connect();try{await client.query('begin');const item=await client.query('select ii.*,i.invoice_type from invoice_items ii join invoices i on i.id=ii.invoice_id where ii.id=$1 for update',[invoiceItemId]);if(!item.rowCount)throw new Error('بند الفاتورة غير موجود');if(Number(serialIds.length)!==Number(item.rows[0].quantity))throw new Error('عدد الأرقام التسلسلية يجب أن يساوي كمية البند');for(const id of serialIds){const s=await client.query('select * from serial_numbers where id=$1 for update',[id]);if(!s.rowCount||String(s.rows[0].product_id)!==String(item.rows[0].product_id))throw new Error('الرقم التسلسلي لا يطابق الصنف');if(item.rows[0].invoice_type==='sale'&&s.rows[0].status!=='in_stock')throw new Error('الرقم التسلسلي غير متاح للبيع');await client.query('insert into invoice_item_serials(invoice_item_id,serial_id) values($1,$2)',[invoiceItemId,id]);const invMeta=await client.query('select customer_id from invoices where id=$1',[item.rows[0].invoice_id]);const customerId=invMeta.rows[0]?.customer_id||null;const sale=item.rows[0].invoice_type==='sale';await client.query('update serial_numbers set status=$1,customer_id=$2,invoice_id=$3,warehouse_id=$4 where id=$5',[sale?'sold':'in_stock',sale?customerId:null,sale?item.rows[0].invoice_id:null,sale?null:s.rows[0].warehouse_id,id]);}await client.query('commit');res.json({ok:true})}catch(e){await client.query('rollback');res.status(400).json({error:e.message})}finally{client.release()}});
app.get('/api/inventory/serials/:serialNo',auth,requirePermission('reports.view'),async(req,res)=>{const r=await pool.query('select s.*,p.code product_code,p.name product_name,w.name warehouse_name,c.name customer_name,i.invoice_no from serial_numbers s join products p on p.id=s.product_id left join warehouses w on w.id=s.warehouse_id left join customers c on c.id=s.customer_id left join invoices i on i.id=s.invoice_id where s.serial_no=$1',[req.params.serialNo]);if(!r.rowCount)return res.status(404).json({error:'الرقم التسلسلي غير موجود'});const h=await pool.query('select iis.*,ii.invoice_id,i.invoice_no,i.invoice_type from invoice_item_serials iis join invoice_items ii on ii.id=iis.invoice_item_id join invoices i on i.id=ii.invoice_id where iis.serial_id=$1 order by i.created_at',[r.rows[0].id]);res.json({...r.rows[0],history:h.rows})});
app.get('/api/accounting/accounts',auth,requirePermission('finance.manage'),async(_,res)=>{const r=await pool.query('select * from accounts where is_active=true order by code');res.json(r.rows)});
app.get('/api/accounting/journal',auth,requirePermission('reports.view'),async(req,res)=>{const limit=Math.min(Number(req.query.limit)||200,1000);const r=await pool.query('select e.*,coalesce(sum(l.debit),0) debit,coalesce(sum(l.credit),0) credit from journal_entries e join journal_lines l on l.entry_id=e.id group by e.id order by e.entry_date desc,e.created_at desc limit $1',[limit]);res.json(r.rows)});
app.get('/api/accounting/trial-balance',auth,requirePermission('reports.view'),async(_,res)=>{const r=await pool.query("select a.code,a.name,a.account_type,coalesce(sum(l.debit),0) debit,coalesce(sum(l.credit),0),coalesce(sum(l.debit-l.credit),0) balance from accounts a left join journal_lines l on l.account_id=a.id where a.is_active=true group by a.id order by a.code");res.json(r.rows)});
app.post('/api/accounting/journal',auth,requirePermission('finance.manage'),async(req,res)=>{const {description,referenceType,referenceId,lines=[]}=req.body||{};const client=await pool.connect();try{await client.query('begin');const id=await journalEntryTx(client,{description,referenceType,referenceId,userId:req.user.sub,lines});await client.query('commit');res.status(201).json({success:true,id})}catch(e){await client.query('rollback');res.status(400).json({error:e.message})}finally{client.release()}});
app.get('/api/reports/profit-and-loss',auth,requirePermission('reports.view'),async(_,res)=>{const r=await pool.query("select a.account_type,sum(l.debit) debit,sum(l.credit) credit,sum(case when a.account_type='revenue' then l.credit-l.debit when a.account_type='expense' then l.debit-l.credit else 0 end) amount from accounts a join journal_lines l on l.account_id=a.id where a.account_type in ('revenue','expense') group by a.account_type");res.json(r.rows)});
app.post('/api/returns',auth,async(req,res)=>{const {returnType,invoiceId,warehouseId,items=[],reason}=req.body||{};if(!['sale','purchase'].includes(returnType)||!invoiceId||!warehouseId||!items.length)return res.status(400).json({error:'بيانات المرتجع غير مكتملة'});if(req.user.role!=='admin'){const needed=returnType==='sale'?'sales.manage':'purchases.manage';const pr=await pool.query('select 1 from users u join roles ro on lower(ro.name)=lower(u.role) join role_permissions rp on rp.role_id=ro.id join permissions p on p.id=rp.permission_id where u.id=$1 and p.code=$2 and u.is_active=true',[req.user.sub,needed]);if(!pr.rowCount)return res.status(403).json({error:'لا تملك صلاحية المرتجع'})}const client=await pool.connect();try{await client.query('begin');const inv=await client.query('select * from invoices where id=$1 for update',[invoiceId]);if(!inv.rowCount||inv.rows[0].invoice_type!==returnType)throw new Error('الفاتورة غير صالحة للمرتجع');const allowedRows=await client.query('select product_id,quantity,unit_price,unit_cost from invoice_items where invoice_id=$1',[invoiceId]);const returnedRows=await client.query('select ri.product_id,coalesce(sum(ri.quantity),0) quantity from return_items ri join returns r on r.id=ri.return_id where r.invoice_id=$1 group by ri.product_id',[invoiceId]);const returned=new Map(returnedRows.rows.map(x=>[String(x.product_id),Number(x.quantity)]));const allowed=new Map(allowedRows.rows.map(x=>[String(x.product_id),Number(x.quantity)-Number(returned.get(String(x.product_id))||0)]));let subtotal=0;for(const x of items){const q=Number(x.quantity);if(!allowed.has(String(x.productId))||q<=0||q>allowed.get(String(x.productId)))throw new Error('كمية المرتجع أكبر من الكمية الأصلية');const source=allowedRows.rows.find(y=>String(y.product_id)===String(x.productId));const price=Number(x.unitPrice??source.unit_price);subtotal+=q*price;if(returnType==='sale'){await client.query('insert into stock_balances(product_id,warehouse_id,quantity) values($1,$2,$3) on conflict(product_id,warehouse_id) do update set quantity=stock_balances.quantity+excluded.quantity',[x.productId,warehouseId,q]);await client.query('insert into product_stock_movements(product_id,warehouse_id,movement_type,quantity,reference,notes) values($1,$2,\'in\',$3,$4,$5)',[x.productId,warehouseId,q,'RET-'+invoiceId,reason||'sale return']);}else{const b=await client.query('select quantity from stock_balances where product_id=$1 and warehouse_id=$2 for update',[x.productId,warehouseId]);if(Number(b.rows[0]?.quantity||0)<q)throw new Error('المخزون غير كاف لمرتجع المشتريات');await client.query('update stock_balances set quantity=quantity-$1 where product_id=$2 and warehouse_id=$3',[q,x.productId,warehouseId]);await client.query('insert into product_stock_movements(product_id,warehouse_id,movement_type,quantity,reference,notes) values($1,$2,\'out\',$3,$4,$5)',[x.productId,warehouseId,q,'RET-'+invoiceId,reason||'purchase return']);}}const invoiceSubtotal=allowedRows.rows.reduce((a,x)=>a+Number(x.quantity)*Number(x.unit_price),0);const invoiceTax=Number(inv.rows[0].tax_amount||0);const taxAmount=invoiceSubtotal>0?Math.min(invoiceTax,invoiceTax*(subtotal/invoiceSubtotal)):0;const total=subtotal+taxAmount;const no='RET-'+Date.now();const ri=await client.query('insert into returns(return_no,return_type,invoice_id,customer_id,supplier_id,warehouse_id,total,reason,created_by) values($1,$2,$3,$4,$5,$6,$7,$8,$9) returning *',[no,returnType,invoiceId,inv.rows[0].customer_id,inv.rows[0].supplier_id,warehouseId,total,reason,req.user.sub]);for(const x of items){const source=allowedRows.rows.find(y=>String(y.product_id)===String(x.productId));const price=Number(x.unitPrice??source.unit_price);await client.query('insert into return_items(return_id,product_id,quantity,unit_price,line_total) values($1,$2,$3,$4,$5)',[ri.rows[0].id,x.productId,x.quantity,price,Number(x.quantity)*price])}if(returnType==='sale'){const cogs=items.reduce((a,x)=>{const s=allowedRows.rows.find(y=>String(y.product_id)===String(x.productId));return a+Number(x.quantity)*Number(s?.unit_cost||0)},0);await journalEntryTx(client,{description:'مرتجع بيع '+no,referenceType:'return',referenceId:ri.rows[0].id,userId:req.user.sub,lines:[{account:'4100',debit:subtotal,credit:0},{account:'2200',debit:taxAmount,credit:0},{account:'1200',debit:0,credit:total}].filter(x=>x.debit||x.credit)});if(cogs>0)await journalEntryTx(client,{description:'عكس تكلفة مرتجع بيع '+no,referenceType:'return',referenceId:ri.rows[0].id,userId:req.user.sub,lines:[{account:'1300',debit:cogs,credit:0},{account:'5100',debit:0,credit:cogs}]})}else{await journalEntryTx(client,{description:'مرتجع شراء '+no,referenceType:'return',referenceId:ri.rows[0].id,userId:req.user.sub,lines:[{account:'2100',debit:total,credit:0},{account:'1300',debit:0,credit:subtotal},{account:'1400',debit:0,credit:taxAmount}].filter(x=>x.debit||x.credit)})}await registerTransactionPosting(client,{transactionType:'return',transactionId:ri.rows[0].id,userId:req.user.sub});await client.query('insert into audit_logs(user_id,action,entity,entity_id,details) values($1,$2,$3,$4,$5)',[req.user.sub,'return.post','return',ri.rows[0].id,JSON.stringify({total,posting:'posted'})]);await client.query('commit');res.status(201).json(ri.rows[0])}catch(e){await client.query('rollback');res.status(400).json({error:e.message})}finally{client.release()}});
app.get('/api/rma',auth,requirePermission('rma.manage'),async(req,res)=>{const r=await pool.query(`select r.*,s.serial_no,c.name customer_name,p.name product_name,ret.return_no,(select ii.warehouse_id from invoice_item_serials iis join invoice_items ii on ii.id=iis.invoice_item_id where iis.serial_id=r.serial_id limit 1) source_warehouse_id,rs.serial_no replacement_serial_no from rma_cases r left join serial_numbers s on s.id=r.serial_id left join serial_numbers rs on rs.id=r.replacement_serial_id left join customers c on c.id=r.customer_id left join products p on p.id=s.product_id left join returns ret on ret.id=r.return_id order by r.created_at desc`);res.json(r.rows)});
app.post('/api/rma',auth,requirePermission('rma.manage'),async(req,res)=>{const {returnId,serialId,customerId,resolution='none',inspectionNotes}=req.body||{};if(!serialId)return res.status(400).json({error:'الرقم التسلسلي مطلوب'});if(!['repair','replacement','refund','none'].includes(resolution))return res.status(400).json({error:'حل RMA غير صحيح'});const client=await pool.connect();try{await client.query('begin');const s=await client.query('select * from serial_numbers where id=$1 for update',[serialId]);if(!s.rowCount)throw new Error('الرقم التسلسلي غير موجود');if(!['sold','returned'].includes(s.rows[0].status))throw new Error('لا يمكن فتح RMA لهذا الـ Serial في حالته الحالية');const existing=await client.query("select 1 from rma_cases where serial_id=$1 and status not in ('closed','rejected','refunded','replaced')",[serialId]);if(existing.rowCount)throw new Error('يوجد RMA مفتوح لهذا الرقم التسلسلي');const no='RMA-'+Date.now();const r=await client.query('insert into rma_cases(rma_no,return_id,serial_id,customer_id,resolution,inspection_notes,created_by) values($1,$2,$3,$4,$5,$6,$7) returning *',[no,returnId||null,serialId,customerId||s.rows[0].customer_id||null,resolution,inspectionNotes||null,req.user.sub]);await client.query("update serial_numbers set status='repair' where id=$1",[serialId]);await client.query('commit');res.status(201).json(r.rows[0])}catch(e){await client.query('rollback');res.status(400).json({error:e.message})}finally{client.release()}});
app.patch('/api/rma/:id',auth,requirePermission('rma.manage'),async(req,res)=>{const {status,resolution,inspectionNotes,replacementSerialId}=req.body||{};const transitions={received:['inspected','rejected'],inspected:['approved','rejected'],approved:['repaired','replaced','refunded','rejected'],repaired:['closed'],replaced:['closed'],refunded:['closed'],rejected:[],closed:[]};const allowed=['received','inspected','approved','rejected','repaired','replaced','refunded','closed'];if(status&&!allowed.includes(status))return res.status(400).json({error:'حالة RMA غير صحيحة'});const client=await pool.connect();try{await client.query('begin');const r=await client.query('select r.*,s.invoice_id,s.product_id,s.customer_id as serial_customer_id,s.warehouse_id from rma_cases r join serial_numbers s on s.id=r.serial_id where r.id=$1 for update',[req.params.id]);if(!r.rowCount)throw new Error('RMA غير موجود');const current=r.rows[0].status;const nextStatus=status||current;if(status&&status!==current&&!(transitions[current]||[]).includes(status))throw new Error('انتقال حالة RMA غير مسموح من الحالة الحالية');const nextResolution=resolution||r.rows[0].resolution;
if(nextStatus==='replaced'&&current!=='replaced'){if(!replacementSerialId)throw new Error('يجب اختيار Serial بديل');const old=r.rows[0];const wi=await client.query('select warehouse_id from invoice_items where id=(select invoice_item_id from invoice_item_serials where serial_id=$1 limit 1)',[old.serial_id]);const warehouseId=wi.rows[0]?.warehouse_id||old.warehouse_id;if(!warehouseId)throw new Error('لا يمكن تحديد مخزن الاستبدال');const ns=await client.query('select * from serial_numbers where id=$1 for update',[replacementSerialId]);if(!ns.rowCount||ns.rows[0].status!=='in_stock')throw new Error('الـ Serial البديل يجب أن يكون متاحاً بالمخزون');if(String(ns.rows[0].product_id)!==String(old.product_id))throw new Error('الـ Serial البديل يجب أن يكون لنفس الصنف');if(String(ns.rows[0].warehouse_id)!==String(warehouseId))throw new Error('الـ Serial البديل يجب أن يكون في نفس المخزن');const used=await client.query('select 1 from rma_replacements where new_serial_id=$1',[replacementSerialId]);if(used.rowCount)throw new Error('الـ Serial البديل مستخدم في RMA أخرى');const bal=await client.query('select quantity from stock_balances where product_id=$1 and warehouse_id=$2 for update',[old.product_id,warehouseId]);if(Number(bal.rows[0]?.quantity||0)<1)throw new Error('رصيد المخزون غير كاف');await client.query('insert into rma_replacements(rma_id,old_serial_id,new_serial_id,warehouse_id,created_by) values($1,$2,$3,$4,$5)',[req.params.id,old.serial_id,replacementSerialId,warehouseId,req.user.sub]);await client.query('update rma_cases set replacement_serial_id=$1 where id=$2',[replacementSerialId,req.params.id]);await client.query('update stock_balances set quantity=quantity+1 where product_id=$1 and warehouse_id=$2',[old.product_id,warehouseId]);await client.query('update stock_balances set quantity=quantity-1 where product_id=$1 and warehouse_id=$2',[old.product_id,warehouseId]);await client.query('insert into product_stock_movements(product_id,warehouse_id,movement_type,quantity,reference,notes) values($1,$2,$3,1,$4,$5)',[old.product_id,warehouseId,'in','RMA-'+old.rma_no,'RMA replacement old serial']);await client.query('insert into product_stock_movements(product_id,warehouse_id,movement_type,quantity,reference,notes) values($1,$2,$3,1,$4,$5)',[old.product_id,warehouseId,'out','RMA-'+old.rma_no,'RMA replacement new serial']);await client.query("update serial_numbers set status='returned',warehouse_id=$2 where id=$1",[old.serial_id,warehouseId]);await client.query("update serial_numbers set status='sold',customer_id=$2,invoice_id=$3,warehouse_id=null where id=$1",[replacementSerialId,old.customer_id||old.serial_customer_id||null,old.invoice_id||null]);}if(['repaired','replaced','refunded'].includes(nextStatus)&&nextResolution==='none')throw new Error('يجب تحديد حل RMA');if(nextStatus==='refunded'&&current!=='refunded'){const invId=r.rows[0].invoice_id;if(!invId)throw new Error('لا توجد فاتورة بيع أصلية لهذا الـ Serial');const inv=await client.query('select * from invoices where id=$1 for update',[invId]);if(!inv.rowCount||inv.rows[0].invoice_type!=='sale')throw new Error('الفاتورة الأصلية غير صالحة للاسترداد');const ii=await client.query('select warehouse_id,quantity,unit_price,unit_cost,discount from invoice_items where id=(select invoice_item_id from invoice_item_serials where serial_id=$1 limit 1) for update',[r.rows[0].serial_id]);if(!ii.rowCount)throw new Error('لا يوجد بند فاتورة مرتبط بالـ Serial');const unitRefund=Number(ii.rows[0].unit_price)-Number(ii.rows[0].discount||0);const cogs=Number(ii.rows[0].unit_cost);const returnWarehouseId=ii.rows[0].warehouse_id;const invoiceSubtotal=Number((await client.query('select coalesce(sum(line_total),0) subtotal from invoice_items where invoice_id=$1',[invId])).rows[0].subtotal||0);const invoiceTax=Number(inv.rows[0].tax_amount||0);const taxRefund=invoiceSubtotal>0?Math.min(invoiceTax,Math.max(0,invoiceTax*(unitRefund/invoiceSubtotal))):0;const no='RET-RMA-'+Date.now();const rr=await client.query('insert into returns(return_no,return_type,invoice_id,customer_id,warehouse_id,total,reason,created_by) values($1,\'sale\',$2,$3,$4,$5,$6,$7) returning id',[no,invId,inv.rows[0].customer_id,returnWarehouseId,unitRefund,'RMA refund '+r.rows[0].rma_no,req.user.sub]);await client.query('insert into return_items(return_id,product_id,quantity,unit_price,line_total) values($1,$2,1,$3,$3)',[rr.rows[0].id,r.rows[0].product_id,unitRefund]);await journalEntryTx(client,{description:'استرداد RMA '+r.rows[0].rma_no,referenceType:'return',referenceId:rr.rows[0].id,userId:req.user.sub,lines:[{account:'4100',debit:unitRefund,credit:0},{account:'2200',debit:taxRefund,credit:0},{account:'1200',debit:0,credit:unitRefund+taxRefund}].filter(x=>x.debit||x.credit)});if(cogs>0)await journalEntryTx(client,{description:'عكس تكلفة RMA '+r.rows[0].rma_no,referenceType:'return',referenceId:rr.rows[0].id,userId:req.user.sub,lines:[{account:'1300',debit:cogs,credit:0},{account:'5100',debit:0,credit:cogs}]});await client.query('insert into stock_balances(product_id,warehouse_id,quantity) values($1,$2,1) on conflict(product_id,warehouse_id) do update set quantity=stock_balances.quantity+1',[r.rows[0].product_id,returnWarehouseId]);await client.query('insert into product_stock_movements(product_id,warehouse_id,movement_type,quantity,reference,notes) values($1,$2,\'in\',1,$3,$4)',[r.rows[0].product_id,returnWarehouseId,no,'RMA refund']);await client.query("update serial_numbers set status='returned' where id=$1",[r.rows[0].serial_id]);await registerTransactionPosting(client,{transactionType:'return',transactionId:rr.rows[0].id,userId:req.user.sub});await client.query('update rma_cases set return_id=$1 where id=$2',[rr.rows[0].id,req.params.id])}await client.query('update rma_cases set status=$1,resolution=$2,inspection_notes=coalesce($3,inspection_notes),updated_at=now() where id=$4',[nextStatus,nextResolution,inspectionNotes||null,req.params.id]);await client.query('insert into audit_logs(user_id,action,entity,entity_id,details) values($1,$2,$3,$4,$5)',[req.user.sub,'rma.status.change','rma_case',req.params.id,JSON.stringify({from:current,to:nextStatus,resolution:nextResolution,replacementSerialId:replacementSerialId||null})]);if(nextStatus==='repaired'){const ri=await client.query('select warehouse_id from invoice_items where id=(select invoice_item_id from invoice_item_serials where serial_id=$1 limit 1)',[r.rows[0].serial_id]);const repairWarehouseId=ri.rows[0]?.warehouse_id||r.rows[0].warehouse_id;if(repairWarehouseId){await client.query('insert into stock_balances(product_id,warehouse_id,quantity) values($1,$2,1) on conflict(product_id,warehouse_id) do update set quantity=stock_balances.quantity+1',[r.rows[0].product_id,repairWarehouseId]);await client.query('insert into product_stock_movements(product_id,warehouse_id,movement_type,quantity,reference,notes) values($1,$2,\'in\',1,$3,$4)',[r.rows[0].product_id,repairWarehouseId,'RMA-'+r.rows[0].rma_no,'RMA repaired return to stock']);await client.query("update serial_numbers set status='in_stock',customer_id=null,invoice_id=null,warehouse_id=$2 where id=$1",[r.rows[0].serial_id,repairWarehouseId])}else await client.query("update serial_numbers set status='in_stock',customer_id=null,invoice_id=null where id=$1",[r.rows[0].serial_id])}else if(['rejected','closed'].includes(nextStatus)&&current!=='repaired')await client.query("update serial_numbers set status='returned' where id=$1",[r.rows[0].serial_id]);else if(nextStatus==='replaced')await client.query("update serial_numbers set status='returned' where id=$1",[r.rows[0].serial_id]);await client.query('commit');const out=await pool.query('select r.*,s.serial_no,c.name customer_name,p.name product_name,ret.return_no from rma_cases r left join serial_numbers s on s.id=r.serial_id left join customers c on c.id=r.customer_id left join products p on p.id=s.product_id left join returns ret on ret.id=r.return_id where r.id=$1',[req.params.id]);res.json(out.rows[0])}catch(e){await client.query('rollback');res.status(400).json({error:e.message})}finally{client.release()}});
app.get('/api/returns',auth,requirePermission('reports.view'),async(_,res)=>{const r=await pool.query('select r.*,i.invoice_no,c.name customer_name,s.name supplier_name from returns r left join invoices i on i.id=r.invoice_id left join customers c on c.id=r.customer_id left join suppliers s on s.id=r.supplier_id order by r.return_date desc,r.created_at desc');res.json(r.rows)});
app.get('/api/admin/roles',auth,requirePermission('users.manage'),async(_,res)=>{const r=await pool.query('select ro.id,ro.name,ro.description,count(rp.permission_id)::int permission_count from roles ro left join role_permissions rp on rp.role_id=ro.id group by ro.id order by ro.name');res.json(r.rows)});app.get('/api/admin/permissions',auth,requirePermission('users.manage'),async(_,res)=>{const r=await pool.query('select id,code,name from permissions order by code');res.json(r.rows)});app.get('/api/admin/roles/:id/permissions',auth,requirePermission('users.manage'),async(req,res)=>{const r=await pool.query('select p.id,p.code,p.name from role_permissions rp join permissions p on p.id=rp.permission_id where rp.role_id=$1 order by p.code',[req.params.id]);res.json(r.rows)});app.put('/api/admin/roles/:id/permissions',auth,requirePermission('users.manage'),async(req,res)=>{const ids=Array.isArray(req.body?.permissionIds)?req.body.permissionIds:[];const client=await pool.connect();try{await client.query('begin');await client.query('delete from role_permissions where role_id=$1',[req.params.id]);if(ids.length)await client.query('insert into role_permissions(role_id,permission_id) select $1,id from permissions where id=any($2::uuid[])',[req.params.id,ids]);await client.query('commit');res.json({ok:true})}catch(e){await client.query('rollback');res.status(400).json({error:e.message})}finally{client.release()}});app.get('/api/admin/users',auth,requirePermission('users.manage'),async(_,res)=>{const r=await pool.query('select id,email,full_name,role,is_active,created_at from users order by full_name');res.json(r.rows)});
app.post('/api/admin/users',auth,requirePermission('users.manage'),async(req,res)=>{const {email,password,fullName,role='sales'}=req.body||{};if(!email||!password||!fullName)return res.status(400).json({error:'بيانات المستخدم غير مكتملة'});const hash=await bcrypt.hash(password,12);const r=await pool.query('insert into users(email,password_hash,full_name,role) values($1,$2,$3,$4) returning id,email,full_name,role,is_active',[email.toLowerCase(),hash,fullName,role]);res.status(201).json(r.rows[0])});
app.patch('/api/admin/users/:id/status',auth,requirePermission('users.manage'),async(req,res)=>{const r=await pool.query('update users set is_active=$1 where id=$2 returning id,email,full_name,role,is_active',[Boolean(req.body?.isActive),req.params.id]);if(!r.rowCount)return res.status(404).json({error:'المستخدم غير موجود'});res.json(r.rows[0])});
app.get('/api/accounting/journal',auth,requirePermission('reports.view'),async(req,res)=>{try{const from=req.query.from||'1900-01-01',to=req.query.to||'2999-12-31';const r=await pool.query(`select je.id,je.entry_no,je.entry_date,je.description,je.reference_type,je.reference_id,coalesce(sum(jl.debit),0) debit,coalesce(sum(jl.credit),0) credit from journal_entries je left join journal_lines jl on jl.entry_id=je.id where je.entry_date between $1 and $2 group by je.id order by je.entry_date desc,je.created_at desc`,[from,to]);res.json(r.rows)}catch(e){res.status(500).json({error:e.message})}});
app.get('/api/accounting/general-ledger',auth,requirePermission('reports.view'),async(req,res)=>{try{const accountId=req.query.accountId||null,from=req.query.from||'1900-01-01',to=req.query.to||'2999-12-31';const r=await pool.query(`select a.id,a.code,a.name,a.account_type,je.entry_no,je.entry_date,je.description,jl.description line_description,jl.debit,jl.credit,je.reference_type,je.reference_id from journal_lines jl join journal_entries je on je.id=jl.entry_id join accounts a on a.id=jl.account_id where je.entry_date between $1 and $2 and ($3::uuid is null or a.id=$3) order by a.code,je.entry_date,je.created_at,jl.id`,[from,to,accountId]);const balances=new Map();const rows=r.rows.map(x=>{const d=Number(x.debit),c=Number(x.credit),prev=balances.get(x.account_id)||0,next=prev+d-c;balances.set(x.account_id,next);return {...x,running_balance:next}});res.json({rows,from,to,accountId})}catch(e){res.status(500).json({error:e.message})}});
app.get('/api/accounting/trial-balance',auth,requirePermission('reports.view'),async(req,res)=>{try{const from=req.query.from||'1900-01-01',to=req.query.to||'2999-12-31';const r=await pool.query(`select a.id,a.code,a.name,a.account_type,coalesce(sum(jl.debit),0) debit,coalesce(sum(jl.credit),0) credit,(coalesce(sum(jl.debit),0)-coalesce(sum(jl.credit),0)) balance from accounts a left join journal_lines jl on jl.account_id=a.id left join journal_entries je on je.id=jl.entry_id and je.entry_date between $1 and $2 where a.is_active=true and (jl.id is null or je.id is not null) group by a.id order by a.code`,[from,to]);res.json(r.rows)}catch(e){res.status(500).json({error:e.message})}});
app.get('/api/accounting/profit-loss',auth,requirePermission('reports.view'),async(req,res)=>{try{const from=req.query.from||'1900-01-01',to=req.query.to||'2999-12-31';const r=await pool.query(`select a.code,a.name,a.account_type,coalesce(sum(jl.credit-jl.debit),0) amount from accounts a left join journal_lines jl on jl.account_id=a.id left join journal_entries je on je.id=jl.entry_id and je.entry_date between $1 and $2 where a.is_active=true and a.account_type in ('revenue','expense') and (jl.id is null or je.id is not null) group by a.id order by a.account_type,a.code`,[from,to]);const rows=r.rows.map(x=>({...x,amount:Number(x.amount)}));const revenue=rows.filter(x=>x.account_type==='revenue').reduce((n,x)=>n+x.amount,0),expenses=rows.filter(x=>x.account_type==='expense').reduce((n,x)=>n+(-x.amount),0);res.json({from,to,revenue,expenses,netProfit:revenue-expenses,rows})}catch(e){res.status(500).json({error:e.message})}});
app.get('/api/accounting/balance-sheet',auth,requirePermission('reports.view'),async(req,res)=>{try{const to=req.query.to||new Date().toISOString().slice(0,10);const r=await pool.query(`select a.code,a.name,a.account_type,coalesce(sum(jl.debit-jl.credit),0) raw_balance from accounts a left join journal_lines jl on jl.account_id=a.id left join journal_entries je on je.id=jl.entry_id and je.entry_date <= $1 where a.is_active=true and a.account_type in ('asset','liability','equity') and (jl.id is null or je.id is not null) group by a.id order by a.account_type,a.code`,[to]);const rows=r.rows.map(x=>{let b=Number(x.raw_balance);if(['liability','equity'].includes(x.account_type))b=-b;return {...x,balance:b}});const net=await pool.query(`select coalesce(sum(case when a.account_type='revenue' then jl.credit-jl.debit when a.account_type='expense' then jl.debit-jl.credit else 0 end),0) net from journal_lines jl join journal_entries je on je.id=jl.entry_id join accounts a on a.id=jl.account_id where je.entry_date <= $1`,[to]);const netIncome=Number(net.rows[0].net||0);res.json({to,rows,netIncome,totalAssets:rows.filter(x=>x.account_type==='asset').reduce((n,x)=>n+x.balance,0),totalLiabilities:rows.filter(x=>x.account_type==='liability').reduce((n,x)=>n+x.balance,0),totalEquity:rows.filter(x=>x.account_type==='equity').reduce((n,x)=>n+x.balance,0)+netIncome})}catch(e){res.status(500).json({error:e.message})}});
app.get('/api/accounting/cash-flow',auth,requirePermission('reports.view'),async(req,res)=>{try{const from=req.query.from||'1900-01-01',to=req.query.to||'2999-12-31';const r=await pool.query(`select je.entry_date,je.entry_no,je.description,je.reference_type,coalesce(sum(jl.debit-jl.credit),0) amount from journal_lines jl join accounts a on a.id=jl.account_id and a.code='1100' join journal_entries je on je.id=jl.entry_id where je.entry_date between $1 and $2 group by je.id order by je.entry_date,je.created_at`,[from,to]);const rows=r.rows.map(x=>({...x,amount:Number(x.amount)}));res.json({from,to,rows,total:rows.reduce((n,x)=>n+x.amount,0)})}catch(e){res.status(500).json({error:e.message})}});
