app.post('/api/suppliers',auth,requirePermission('suppliers.manage'),async(req,res)=>{const {name,phone,openingBalance=0}=req.body||{};if(!name)return res.status(400).json({error:'اسم المورد مطلوب'});const r=await pool.query('insert into suppliers(name,phone,opening_balance) values($1,$2,$3) returning *',[name,phone,openingBalance]);res.status(201).json(r.rows[0])});
app.post('/api/products',auth,requirePermission('products.manage'),async(req,res)=>{const {code,name,category,unit='قطعة',cost=0,price=0,minStock=0,openingStock=0,trackSerial=false}=req.body||{};if(!code||!name)return res.status(400).json({error:'كود واسم الصنف مطلوبان'});const client=await pool.connect();try{await client.query('begin');let cat=await client.query('select id from product_categories where name=$1',[category||'عام']);if(!cat.rowCount)cat=await client.query('insert into product_categories(name) values($1) returning id',[category||'عام']);const p=await client.query('insert into products(code,name,category_id,unit,cost,price,min_stock,track_serial) values($1,$2,$3,$4,$5,$6,$7,$8) returning *',[code,name,cat.rows[0].id,unit,cost,price,minStock,Boolean(trackSerial)]);const w=await client.query('select id from warehouses order by name limit 1');if(w.rowCount){await client.query('insert into stock_balances(product_id,warehouse_id,quantity) values($1,$2,$3) on conflict(product_id,warehouse_id) do update set quantity=excluded.quantity',[p.rows[0].id,w.rows[0].id,openingStock]);if(openingStock)await client.query('insert into product_stock_movements(product_id,warehouse_id,movement_type,quantity,reference) values($1,$2,$3,$4,$5)',[p.rows[0].id,w.rows[0].id,'adjustment',openingStock,'opening']);}await client.query('commit');res.status(201).json(p.rows[0])}catch(e){await client.query('rollback');throw e}finally{client.release()}});
app.post('/api/stock/movement',auth,requirePermission('inventory.manage'),async(req,res)=>{const {productId,warehouseId,movementType,quantity,reference,notes}=req.body||{};if(!productId||!warehouseId||!movementType||!quantity)return res.status(400).json({error:'بيانات حركة المخزون غير مكتملة'});const delta=movementType==='out'?-Math.abs(quantity):Number(quantity);const client=await pool.connect();try{await client.query('begin');const s=await client.query('select quantity from stock_balances where product_id=$1 and warehouse_id=$2 for update',[productId,warehouseId]);const current=Number(s.rows[0]?.quantity||0);if(current+delta<0)throw Object.assign(new Error('الرصيد غير كاف'),{status:409});await client.query('insert into stock_balances(product_id,warehouse_id,quantity) values($1,$2,$3) on conflict(product_id,warehouse_id) do update set quantity=stock_balances.quantity+$3',[productId,warehouseId,delta]);await client.query('insert into product_stock_movements(product_id,warehouse_id,movement_type,quantity,reference,notes) values($1,$2,$3,$4,$5,$6)',[productId,warehouseId,movementType,delta,reference,notes]);await client.query('insert into audit_logs(user_id,action,entity,entity_id,details) values($1,$2,$3,$4,$5)',[req.user.sub,'stock.movement','product',productId,JSON.stringify({warehouseId,movementType,quantity:delta})]);await client.query('commit');res.status(201).json({success:true,newQuantity:current+delta})}catch(e){await client.query('rollback');res.status(e.status||500).json({error:e.message})}finally{client.release()}});
async function nextNo(prefix,table,col){const r=await pool.query(`select count(*)::int+1 n from ${table}`);return prefix+'-'+String(r.rows[0].n).padStart(6,'0')}
app.post('/api/sales-orders',auth,requirePermission('sales.manage'),async(req,res)=>{const {customerId,items=[],tax=0}=req.body||{};if(!customerId||!items.length)return res.status(400).json({error:'العميل والأصناف مطلوبان'});const client=await pool.connect();try{await client.query('begin');let subtotal=0;for(const i of items)subtotal+=Number(i.quantity)*Number(i.unitPrice)-Number(i.discount||0);const total=subtotal+Number(tax||0),no='SO-'+Date.now();const o=await client.query('insert into sales_orders(order_no,customer_id,status,subtotal,tax,total) values($1,$2,$3,$4,$5,$6) returning *',[no,customerId,'confirmed',subtotal,tax,total]);for(const i of items)await client.query('insert into sales_order_items(order_id,product_id,quantity,unit_price,discount,line_total) values($1,$2,$3,$4,$5,$6)',[o.rows[0].id,i.productId,i.quantity,i.unitPrice,i.discount||0,Number(i.quantity)*Number(i.unitPrice)-Number(i.discount||0)]);await client.query('insert into audit_logs(user_id,action,entity,entity_id,details) values($1,$2,$3,$4,$5)',[req.user.sub,'sales.order.create','sales_order',o.rows[0].id,JSON.stringify({total})]);await client.query('commit');res.status(201).json(o.rows[0])}catch(e){await client.query('rollback');res.status(500).json({error:e.message})}finally{client.release()}});
app.post('/api/purchase-orders',auth,requirePermission('purchases.manage'),async(req,res)=>{const {supplierId,items=[],tax=0}=req.body||{};if(!supplierId||!items.length)return res.status(400).json({error:'المورد والأصناف مطلوبان'});const client=await pool.connect();try{await client.query('begin');let subtotal=0;for(const i of items)subtotal+=Number(i.quantity)*Number(i.unitCost)-Number(i.discount||0);const total=subtotal+Number(tax||0),no='PO-'+Date.now();const o=await client.query('insert into purchase_orders(order_no,supplier_id,status,subtotal,tax,total) values($1,$2,$3,$4,$5,$6) returning *',[no,supplierId,'confirmed',subtotal,tax,total]);for(const i of items)await client.query('insert into purchase_order_items(order_id,product_id,quantity,unit_cost,discount,line_total) values($1,$2,$3,$4,$5,$6)',[o.rows[0].id,i.productId,i.quantity,i.unitCost,i.discount||0,Number(i.quantity)*Number(i.unitCost)-Number(i.discount||0)]);await client.query('insert into audit_logs(user_id,action,entity,entity_id,details) values($1,$2,$3,$4,$5)',[req.user.sub,'purchase.order.create','purchase_order',o.rows[0].id,JSON.stringify({total})]);await client.query('commit');res.status(201).json(o.rows[0])}catch(e){await client.query('rollback');res.status(500).json({error:e.message})}finally{client.release()}});
app.post('/api/payments',auth,requirePermission('finance.manage'),async(req,res)=>{const {paymentType,customerId,supplierId,cashboxId,amount,reference,notes}=req.body||{};if(!paymentType||!cashboxId||!amount)return res.status(400).json({error:'بيانات السداد غير مكتملة'});const client=await pool.connect();try{await client.query('begin');const no='PAY-'+Date.now();const p=await client.query('insert into payments(payment_no,payment_type,customer_id,supplier_id,cashbox_id,amount,reference,notes) values($1,$2,$3,$4,$5,$6,$7,$8) returning *',[no,paymentType,customerId||null,supplierId||null,cashboxId,amount,reference,notes]);await client.query('insert into cashbox_transactions(cashbox_id,transaction_type,amount,reference,description) values($1,$2,$3,$4,$5)',[cashboxId,paymentType,amount,no,notes||'']);await journalEntryTx(client,{description:(paymentType==='receipt'?'تحصيل من عميل ':'سداد لمورد ')+no,referenceType:'payment',referenceId:p.rows[0].id,userId:req.user.sub,lines:paymentType==='receipt'?[{account:'1100',debit:Number(amount),credit:0},{account:'1200',debit:0,credit:Number(amount)}]:[{account:'2100',debit:Number(amount),credit:0},{account:'1100',debit:0,credit:Number(amount)}]});await registerTransactionPosting(client,{transactionType:'payment',transactionId:p.rows[0].id,userId:req.user.sub});await client.query('insert into audit_logs(user_id,action,entity,entity_id,details) values($1,$2,$3,$4,$5)',[req.user.sub,'payment.post','payment',p.rows[0].id,JSON.stringify({amount,paymentType,posting:'posted'})]);await client.query('commit');res.status(201).json(p.rows[0])}catch(e){await client.query('rollback');res.status(500).json({error:e.message})}finally{client.release()}});
app.post('/api/finance/expenses',auth,requirePermission('finance.manage'),async(req,res)=>{const {category,description,amount,cashboxId}=req.body||{};const n=Number(amount);if(!category||!cashboxId||!Number.isFinite(n)||n<=0)return res.status(400).json({error:'بيانات المصروف غير مكتملة'});const client=await pool.connect();try{await client.query('begin');const no='EXP-'+Date.now();const e=await client.query('insert into expenses(expense_no,category,description,amount,cashbox_id,created_by) values($1,$2,$3,$4,$5,$6) returning *',[no,category,description||'',n,cashboxId,req.user.sub]);await client.query('insert into cashbox_transactions(cashbox_id,transaction_type,amount,reference,description) values($1,$2,$3,$4,$5)',[cashboxId,'payment',n,no,description||category]);await journalEntryTx(client,{description:'مصروف '+no,referenceType:'expense',referenceId:e.rows[0].id,userId:req.user.sub,lines:[{account:'5200',debit:n,credit:0},{account:'1100',debit:0,credit:n}]});await registerTransactionPosting(client,{transactionType:'expense',transactionId:e.rows[0].id,userId:req.user.sub});await client.query('insert into audit_logs(user_id,action,entity,entity_id,details) values($1,$2,$3,$4,$5)',[req.user.sub,'expense.post','expense',e.rows[0].id,JSON.stringify({amount:n,posting:'posted'})]);await client.query('commit');res.status(201).json(e.rows[0])}catch(e){await client.query('rollback');res.status(500).json({error:e.message})}finally{client.release()}});
app.post('/api/finance/incomes',auth,requirePermission('finance.manage'),async(req,res)=>{const {category,description,amount,cashboxId}=req.body||{};const n=Number(amount);if(!category||!cashboxId||!Number.isFinite(n)||n<=0)return res.status(400).json({error:'بيانات الإيراد غير مكتملة'});const client=await pool.connect();try{await client.query('begin');const no='INC-'+Date.now();const e=await client.query('insert into incomes(income_no,category,description,amount,cashbox_id,created_by) values($1,$2,$3,$4,$5,$6) returning *',[no,category,description||'',n,cashboxId,req.user.sub]);await client.query('insert into cashbox_transactions(cashbox_id,transaction_type,amount,reference,description) values($1,$2,$3,$4,$5)',[cashboxId,'receipt',n,no,description||category]);await journalEntryTx(client,{description:'إيراد '+no,referenceType:'income',referenceId:e.rows[0].id,userId:req.user.sub,lines:[{account:'1100',debit:n,credit:0},{account:'4200',debit:0,credit:n}]});await registerTransactionPosting(client,{transactionType:'income',transactionId:e.rows[0].id,userId:req.user.sub});await client.query('insert into audit_logs(user_id,action,entity,entity_id,details) values($1,$2,$3,$4,$5)',[req.user.sub,'income.post','income',e.rows[0].id,JSON.stringify({amount:n,posting:'posted'})]);await client.query('commit');res.status(201).json(e.rows[0])}catch(e){await client.query('rollback');res.status(500).json({error:e.message})}finally{client.release()}});
