app.post('/api/admin/employees',auth,async(req,res)=>{const {fullName,phone,email,departmentId,jobTitle,hireDate}=req.body||{};if(!fullName)return res.status(400).json({error:'اسم الموظف مطلوب'});const no='EMP-'+Date.now();const r=await pool.query('insert into employees(employee_no,full_name,phone,email,department_id,job_title,hire_date) values($1,$2,$3,$4,$5,$6,$7) returning *',[no,fullName,phone,email,departmentId||null,jobTitle,hireDate||null]);res.status(201).json(r.rows[0])});
