app.get('/api/audit',auth,async(req,res)=>{const {entity,userId}=req.query;const args=[];const where=[];if(entity){args.push(entity);where.push('a.entity=$'+args.length)}if(userId){args.push(userId);where.push('a.user_id=$'+args.length)}const q='select a.id,a.action,a.entity,a.entity_id,a.details,a.created_at,a.user_id,u.full_name,u.email from audit_logs a left join users u on u.id=a.user_id '+(where.length?'where '+where.join(' and '):'')+' order by a.created_at desc limit 300';const r=await pool.query(q,args);res.json(r.rows)});
