app.get('/api/accounting/journal',auth,requirePermission('reports.view'),async(req,res)=>{try{const from=req.query.from||'1900-01-01',to=req.query.to||'2999-12-31';const r=await pool.query(`select je.id,je.entry_no,je.entry_date,je.description,je.reference_type,je.reference_id,coalesce(sum(jl.debit),0) debit,coalesce(sum(jl.credit),0) credit from journal_entries je left join journal_lines jl on jl.entry_id=je.id where je.entry_date between $1 and $2 group by je.id order by je.entry_date desc,je.created_at desc`,[from,to]);res.json(r.rows)}catch(e){res.status(500).json({error:e.message})}});
app.get('/api/accounting/general-ledger',auth,requirePermission('reports.view'),async(req,res)=>{try{const accountId=req.query.accountId||null,from=req.query.from||'1900-01-01',to=req.query.to||'2999-12-31';const r=await pool.query(`select a.id,a.code,a.name,a.account_type,je.entry_no,je.entry_date,je.description,jl.description line_description,jl.debit,jl.credit,je.reference_type,je.reference_id from journal_lines jl join journal_entries je on je.id=jl.entry_id join accounts a on a.id=jl.account_id where je.entry_date between $1 and $2 and ($3::uuid is null or a.id=$3) order by a.code,je.entry_date,je.created_at,jl.id`,[from,to,accountId]);const balances=new Map();const rows=r.rows.map(x=>{const d=Number(x.debit),c=Number(x.credit),prev=balances.get(x.account_id)||0,next=prev+d-c;balances.set(x.account_id,next);return {...x,running_balance:next}});res.json({rows,from,to,accountId})}catch(e){res.status(500).json({error:e.message})}});
