app.post('/api/projects',auth,async(req,res)=>{const {name,customerId,projectType='IT',contractValue=0,startDate,endDate,notes}=req.body||{};if(!name)return res.status(400).json({error:'اسم المشروع مطلوب'});const no='PRJ-'+Date.now();const r=await pool.query('insert into projects(project_no,name,customer_id,start_date,end_date,budget,description) values($1,$2,$3,$4,$5,$6,$7) returning *',[no,name,customerId||null,startDate||null,endDate||null,Number(contractValue)||0,notes||null]);res.status(201).json(r.rows[0])});
app.patch('/api/tickets/:id',auth,async(req,res)=>{const {status,priority,title,description,assignedTo}=req.body||{};const r=await pool.query(`update service_tickets set status=coalesce($1,status),priority=coalesce($2,priority),title=coalesce($3,title),description=coalesce($4,description),assigned_to=coalesce($5,assigned_to),closed_at=case when $1='closed' then coalesce(closed_at,now()) else closed_at end where id=$6 returning *`,[status??null,priority??null,title??null,description??null,assignedTo??null,req.params.id]);if(!r.rowCount)return res.status(404).json({error:'التذكرة غير موجودة'});await pool.query('insert into audit_logs(user_id,action,entity,entity_id,details) values($1,$2,$3,$4,$5)',[req.user.sub,'service.ticket.update','service_ticket',req.params.id,JSON.stringify({status,priority,assignedTo})]);res.json(r.rows[0])});
