app.get('/api/operations/summary',auth,async(_,res)=>{const [l,o,p,t]=await Promise.all([pool.query("select count(*)::int count from crm_leads where status not in ('won','lost')"),pool.query("select count(*)::int count from opportunities where stage not in ('won','lost')"),pool.query("select count(*)::int count from projects where status not in ('completed','cancelled')"),pool.query("select count(*)::int count from service_tickets where status not in ('closed','cancelled')")]);res.json({leads:l.rows[0].count,opportunities:o.rows[0].count,projects:p.rows[0].count,tickets:t.rows[0].count})});
app.get('/api/dashboard',auth,async(_,res)=>{
 try{
  const [sales,purchases,receivables,payables,cash,stock,low,tickets,projects,tasks,recent]=await Promise.all([
   pool.query("select coalesce(sum(total),0) total,count(*)::int count from invoices where invoice_type='sale' and invoice_date>=date_trunc('month',current_date)::date and invoice_date<current_date+1"),
   pool.query("select coalesce(sum(total),0) total,count(*)::int count from invoices where invoice_type='purchase' and invoice_date>=date_trunc('month',current_date)::date and invoice_date<current_date+1"),
   pool.query("select coalesce(sum(i.total-coalesce((select sum(p.amount) from invoice_payments ip join payments p on p.id=ip.payment_id where ip.invoice_id=i.id),0)),0) balance from invoices i where i.invoice_type='sale'"),
   pool.query("select coalesce(sum(i.total-coalesce((select sum(p.amount) from invoice_payments ip join payments p on p.id=ip.payment_id where ip.invoice_id=i.id),0)),0) balance from invoices i where i.invoice_type='purchase'"),
   pool.query("select coalesce(sum(case when transaction_type in ('receipt','income') then amount when transaction_type in ('payment','expense') then -amount else 0 end),0) balance from cashbox_transactions"),
   pool.query("select count(distinct p.id)::int products,coalesce(sum(sb.quantity),0) units,coalesce(sum(sb.quantity*coalesce(p.cost,0)),0) value from products p left join stock_balances sb on sb.product_id=p.id where p.is_active=true"),
   pool.query("select count(*)::int count from products p where p.is_active=true and coalesce((select sum(sb.quantity) from stock_balances sb where sb.product_id=p.id),0)<=p.min_stock"),
   pool.query("select count(*)::int count from service_tickets where status not in ('closed','cancelled')"),
   pool.query("select count(*)::int count from projects where status not in ('completed','cancelled')"),
   pool.query("select count(*)::int count from project_tasks where status not in ('done','completed','cancelled') and due_date is not null and due_date<current_date"),
   pool.query("select invoice_no id,invoice_type type,invoice_date date,total,coalesce(c.name,s.name,'') party from invoices i left join customers c on c.id=i.customer_id left join suppliers s on s.id=i.supplier_id order by invoice_date desc,created_at desc limit 8")
  ]);
  res.json({
   salesMonth:{total:Number(sales.rows[0].total),count:sales.rows[0].count},
   purchasesMonth:{total:Number(purchases.rows[0].total),count:purchases.rows[0].count},
   receivables:Number(receivables.rows[0].balance),
   payables:Number(payables.rows[0].balance),
   cash:Number(cash.rows[0].balance),
   stock:{products:stock.rows[0].products,units:Number(stock.rows[0].units),value:Number(stock.rows[0].value)},
   lowStock:low.rows[0].count,openTickets:tickets.rows[0].count,activeProjects:projects.rows[0].count,overdueTasks:tasks.rows[0].count,
   recent:recent.rows.map(x=>({...x,total:Number(x.total),type:x.type==='sale'?'بيع':'شراء'}))
  });
 }catch(e){console.error(e);res.status(500).json({error:'تعذر تحميل مؤشرات لوحة التحكم'})}
});
async function bootstrap(){await pool.query(`
CREATE TABLE IF NOT EXISTS branches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text UNIQUE NOT NULL,address text,phone text,is_active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS departments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text UNIQUE NOT NULL,branch_id uuid REFERENCES branches(id),is_active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS employees(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),employee_no text UNIQUE NOT NULL,full_name text NOT NULL,phone text,email text,department_id uuid REFERENCES departments(id),job_title text,hire_date date,status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS expenses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),expense_no text UNIQUE NOT NULL,expense_date date NOT NULL DEFAULT current_date,category text NOT NULL,description text,amount numeric(14,2) NOT NULL CHECK(amount>0),cashbox_id uuid REFERENCES cashboxes(id),created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS incomes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),income_no text UNIQUE NOT NULL,income_date date NOT NULL DEFAULT current_date,category text NOT NULL,description text,amount numeric(14,2) NOT NULL CHECK(amount>0),cashbox_id uuid REFERENCES cashboxes(id),created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS returns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),return_no text UNIQUE NOT NULL,return_type text NOT NULL CHECK(return_type IN('sale','purchase')),invoice_id uuid REFERENCES invoices(id),customer_id uuid REFERENCES customers(id),supplier_id uuid REFERENCES suppliers(id),warehouse_id uuid REFERENCES warehouses(id),return_date date NOT NULL DEFAULT current_date,total numeric(14,2) NOT NULL DEFAULT 0,reason text,status text NOT NULL DEFAULT 'posted',created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS return_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),return_id uuid NOT NULL REFERENCES returns(id) ON DELETE CASCADE,product_id uuid NOT NULL REFERENCES products(id),quantity numeric(14,3) NOT NULL CHECK(quantity>0),unit_price numeric(14,2) NOT NULL DEFAULT 0,line_total numeric(14,2) NOT NULL DEFAULT 0);
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.name='admin' ON CONFLICT DO NOTHING;
`)}
app.get('/api/cash/expenses',auth,async(_,res)=>{const r=await pool.query('select e.*,c.name cashbox_name from expenses e left join cashboxes c on c.id=e.cashbox_id order by e.expense_date desc,e.created_at desc');res.json(r.rows)});
app.post('/api/cash/expenses',auth,async(req,res)=>{const {category,description,amount,cashboxId}=req.body||{};if(!category||Number(amount)<=0||!cashboxId)return res.status(400).json({error:'بيانات المصروف غير مكتملة'});const client=await pool.connect();try{await client.query('begin');const no='EXP-'+Date.now();const e=await client.query('insert into expenses(expense_no,category,description,amount,cashbox_id,created_by) values($1,$2,$3,$4,$5,$6) returning *',[no,category,description,amount,cashboxId,req.user.sub]);await client.query('insert into cashbox_transactions(cashbox_id,transaction_type,amount,reference,description) values($1,\'payment\',$2,$3,$4)',[cashboxId,amount,no,description||category]);await journalEntryTx(client,{description:category,referenceType:'expense',referenceId:e.rows[0].id,userId:req.user.sub,lines:[{account:'5200',debit:Number(amount),credit:0},{account:'1100',debit:0,credit:Number(amount)}]});await client.query('commit');res.status(201).json(e.rows[0])}catch(e){await client.query('rollback');res.status(400).json({error:e.message})}finally{client.release()}});
app.get('/api/cash/incomes',auth,async(_,res)=>{const r=await pool.query('select i.*,c.name cashbox_name from incomes i left join cashboxes c on c.id=i.cashbox_id order by i.income_date desc,i.created_at desc');res.json(r.rows)});
app.post('/api/cash/incomes',auth,async(req,res)=>{const {category,description,amount,cashboxId}=req.body||{};if(!category||Number(amount)<=0||!cashboxId)return res.status(400).json({error:'بيانات الإيراد غير مكتملة'});const client=await pool.connect();try{await client.query('begin');const no='INC-'+Date.now();const i=await client.query('insert into incomes(income_no,category,description,amount,cashbox_id,created_by) values($1,$2,$3,$4,$5,$6) returning *',[no,category,description,amount,cashboxId,req.user.sub]);await client.query('insert into cashbox_transactions(cashbox_id,transaction_type,amount,reference,description) values($1,\'receipt\',$2,$3,$4)',[cashboxId,amount,no,description||category]);await journalEntryTx(client,{description:category,referenceType:'income',referenceId:i.rows[0].id,userId:req.user.sub,lines:[{account:'1100',debit:Number(amount),credit:0},{account:'4200',debit:0,credit:Number(amount)}]});await client.query('commit');res.status(201).json(i.rows[0])}catch(e){await client.query('rollback');res.status(400).json({error:e.message})}finally{client.release()}});
app.get('/api/attendance',auth,async(req,res)=>{const from=req.query.from||new Date().toISOString().slice(0,10),to=req.query.to||from;const r=await pool.query('select a.*,e.employee_no,e.full_name,d.name department_name from attendance_records a join employees e on e.id=a.employee_id left join departments d on d.id=e.department_id where a.attendance_date between $1 and $2 order by a.attendance_date desc,e.full_name',[from,to]);res.json(r.rows)});
app.post('/api/attendance',auth,async(req,res)=>{const {employeeId,attendanceDate,checkIn,checkOut,status='present',notes}=req.body||{};if(!employeeId||!attendanceDate)return res.status(400).json({error:'الموظف والتاريخ مطلوبان'});const r=await pool.query('insert into attendance_records(employee_id,attendance_date,check_in,check_out,status,notes) values($1,$2,$3,$4,$5,$6) on conflict(employee_id,attendance_date) do update set check_in=excluded.check_in,check_out=excluded.check_out,status=excluded.status,notes=excluded.notes returning *',[employeeId,attendanceDate,checkIn||null,checkOut||null,status,notes||null]);res.status(201).json(r.rows[0])});
