app.get('/api/inventory/valuation',auth,requirePermission('reports.view'),async(_,res)=>{const r=await pool.query('select w.id warehouse_id,w.name warehouse_name,count(distinct sb.product_id)::int products,coalesce(sum(sb.quantity),0) units,coalesce(sum(sb.quantity*coalesce(p.cost,0)),0)::numeric(14,2) value from stock_balances sb join warehouses w on w.id=sb.warehouse_id join products p on p.id=sb.product_id group by w.id,w.name order by w.name');res.json(r.rows)});

