app.get('/api/service/visits',auth,async(_,res)=>{const r=await pool.query('select v.*,c.name customer_name,t.id technician_id,e.full_name technician_name,p.name project_name from site_visits v left join customers c on c.id=v.customer_id left join technicians t on t.id=v.technician_id left join employees e on e.id=t.employee_id left join projects p on p.id=v.project_id order by v.scheduled_at desc nulls last');res.json(r.rows)});
app.post('/api/service/visits',auth,async(req,res)=>{const {customerId,projectId,technicianId,scheduledAt,status='scheduled',notes}=req.body||{};const no='VIS-'+Date.now();const r=await pool.query('insert into site_visits(visit_no,customer_id,project_id,technician_id,scheduled_at,status,notes) values($1,$2,$3,$4,$5,$6,$7) returning *',[no,customerId||null,projectId||null,technicianId||null,scheduledAt||null,status,notes||'']);res.status(201).json(r.rows[0])});
app.get('/api/service/assets',auth,async(_,res)=>{const r=await pool.query('select a.*,c.name customer_name from customer_assets a left join customers c on c.id=a.customer_id order by a.warranty_end nulls last,a.name');res.json(r.rows)});
app.get('/api/service/contracts',auth,async(_,res)=>{const r=await pool.query('select m.*,c.name customer_name from maintenance_contracts m left join customers c on c.id=m.customer_id order by m.end_date nulls last');res.json(r.rows)});
async function generateSystemNotifications(){try{const users=await pool.query("select id from users where is_active=true and role in('admin','manager')");for(const u of users.rows){const low=await pool.query("select p.id,p.name,coalesce(sum(sb.quantity),0) quantity,p.min_stock from products p left join stock_balances sb on sb.product_id=p.id where p.is_active=true group by p.id having coalesce(sum(sb.quantity),0)<=p.min_stock order by p.name limit 20");for(const x of low.rows){const title='مخزون منخفض: '+x.name;const message='الرصيد الحالي '+x.quantity+' والحد الأدنى '+x.min_stock;await pool.query("insert into notifications(user_id,title,message) select $1,$2,$3 where not exists(select 1 from notifications where user_id=$1 and title=$2 and created_at>now()-interval '24 hours')",[u.id,title,message])}const tasks=await pool.query("select id,title,due_date from project_tasks where status not in('done','completed') and due_date<current_date order by due_date limit 20");for(const x of tasks.rows){const title='مهمة مشروع متأخرة: '+x.title;const message='تاريخ الاستحقاق '+x.due_date;await pool.query("insert into notifications(user_id,title,message) select $1,$2,$3 where not exists(select 1 from notifications where user_id=$1 and title=$2 and created_at>now()-interval '24 hours')",[u.id,title,message])}const tickets=await pool.query("select id,ticket_no,title,due_date from service_tickets where status not in('closed','resolved') and due_date<current_date order by due_date limit 20");for(const x of tickets.rows){const title='بلاغ خدمة متأخر: '+x.ticket_no;const message=x.title+' — موعد الاستحقاق '+x.due_date;await pool.query("insert into notifications(user_id,title,message) select $1,$2,$3 where not exists(select 1 from notifications where user_id=$1 and title=$2 and created_at>now()-interval '24 hours')",[u.id,title,message])}}}catch(e){console.error('notification generation failed',e.message)}}
app.get('/api/notifications',auth,async(req,res)=>{await generateSystemNotifications();const r=await pool.query('select * from notifications where user_id=$1 order by created_at desc limit 100',[req.user.sub]);res.json(r.rows)});
app.post('/api/notifications/:id/read',auth,async(req,res)=>{const r=await pool.query('update notifications set read_at=now() where id=$1 and user_id=$2 returning *',[req.params.id,req.user.sub]);res.json(r.rows[0]||null)});
app.get('/api/audit',auth,async(req,res)=>{const {entity,userId}=req.query;const args=[];const where=[];if(entity){args.push(entity);where.push('a.entity=$'+args.length)}if(userId){args.push(userId);where.push('a.user_id=$'+args.length)}const q='select a.id,a.action,a.entity,a.entity_id,a.details,a.created_at,a.user_id,u.full_name,u.email from audit_logs a left join users u on u.id=a.user_id '+(where.length?'where '+where.join(' and '):'')+' order by a.created_at desc limit 300';const r=await pool.query(q,args);res.json(r.rows)});
app.use((e,_,res,__)=>(console.error(e),res.status(500).json({error:'حدث خطأ في الخادم'})));
